import { ImageResponse } from "next/og";

export const size = { width: 180, height: 180 };
export const contentType = "image/png";

// Masque doré rastérisé depuis public/images/logo_totem_1.svg (même logo que
// la nav/le footer), encodé en base64 : next/og (Satori) ne sait pas charger
// un fichier local par chemin, seulement une URL distante ou une data URI.
const LOGO =
  "data:image/png;base64,";

export default function AppleIcon() {
  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          background: "#0D0D1A",
        }}
      >
        <img src={LOGO} width={124} height={124} alt="" />
      </div>
    ),
    { ...size },
  );
}
